# Minimal reproduction generated by stutter for nihalashetty/Forge @ 25074df.
# usage: BASE_URL=http://127.0.0.1:3000 ./repro.sh [faulted|clean]
#   faulted: the delivery order that breaks; clean: the original order.
set -euo pipefail
cd "$(dirname "$0")"
: "${BASE_URL:?set BASE_URL to the running service}"
SECRET=""
send() {
  local f=$1 path=$2 method=${3:-POST} t sig
  local hdr=()
  local STATIC=( -H "Authorization: Bearer stutter-service-token" )
  curl -sS -o /dev/null -w "$f %{http_code}\n" -X "$method" "$BASE_URL$path" -H 'Content-Type: application/json' ${hdr[@]+"${hdr[@]}"} ${STATIC[@]+"${STATIC[@]}"} --data-binary @"$f"
}
if [ "${1:-faulted}" = clean ]; then
  send 0.json "/v1/projects/74ed7105-e6a4-47b7-a571-172b4eb7af47/run" POST
else
  # send, kill the service after its commit 8, restart, resend: needs stutter's wire proxy; curl cannot stop a process at a commit
  send 0.json "/v1/projects/74ed7105-e6a4-47b7-a571-172b4eb7af47/run" POST
fi
